async function save(v:Entry){setError('');try{const r=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json','x-dinner-profile':person},body:JSON.stringify(v)});if(!r.ok){const failure=await r.json() as {error?:string};throw Error(failure.error||'That change was not saved. Please try again.')}const stored=await r.json() as Entry;setRows(p=>[...p.filter(x=>x.id!==v.id),stored]);return true}catch(e){setError(e instanceof Error?e.message:'That change was not saved. Please try again.');return false}}
