 const existing=meals.find(item=>item.name.trim().toLocaleLowerCase()===name.toLocaleLowerCase());
 setBusy(true);
 if(name&&!existing&&!(await save({id:crypto.randomUUID(),type:'meal',name,kind:'Cook',requestedBy:person}))){setBusy(false);return}
