<div className="sides">{sides.map(s=><p key={s.id}>{foodIcon(s.text)} {s.text}<small>{s.person} {!past&&s.person===person&&<button onClick={()=>remove(s.id)} aria-label="Remove your side">×</button>}</small></p>)}</div>
{!past&&(sideDate===key?<form onSubmit={async e=>{e.preventDefault();const input=e.currentTarget.elements.namedItem('side') as HTMLInputElement;if(input.value.trim()&&await save({id:crypto.randomUUID(),type:'note',target:key,side:true,text:input.value.trim(),person}))setSideDate('')}}><input autoFocus required name="side" aria-label={'Side for '+key} placeholder="Side name" maxLength={250}/><div className="side-form-actions"><button className="small" type="submit">Add</button><button className="small" type="button" onClick={()=>setSideDate('')}>Cancel</button></div></form>:<div className="day-action-menu"><button type="button" onClick={()=>openMealPicker(key)}>＋ Add Meal</button></div>)}
